// how heightened spells scale with caster/slot rank. Full tier-by-tier text stays in `desc`.
export const ALCHEMICAL_ITEMS = [
  { name: 'Acid Flask', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d6', desc: 'This flask filled with corrosive acid deals 1 acid damage, the listed persistent acid damage, and the listed acid splash damage. Many types grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d6 persistent acid damage and 1 acid splash damage. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d6 persistent acid damage and 2 acid splash damage. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d6 persistent acid damage and 3 acid splash damage. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d6 persistent acid damage and 4 acid splash damage.', tiers: [{ name: 'Lesser', level: 1, damage: '1d6', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d6', splash: 2 }, { name: 'Greater', level: 11, damage: '3d6', splash: 3 }, { name: 'Major', level: 17, damage: '4d6', splash: 4 }] },
  { name: 'Alchemist’s Fire', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d8', desc: 'Alchemist’s fire is a combination of volatile liquids that ignite when exposed to air. Alchemist’s fire deals the listed fire damage, persistent fire damage, and splash damage. Many types grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d8 fire damage, 1 persistent fire damage, and 1 fire splash damage. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d8 fire damage, 2 persistent fire damage, and 2 fire splash damage. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d8 fire damage, 3 persistent fire damage, and 3 fire splash damage. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d8 fire damage, 4 persistent fire damage, and 4 fire splash damage.', tiers: [{ name: 'Lesser', level: 1, damage: '1d8', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d8', splash: 2 }, { name: 'Greater', level: 11, damage: '3d8', splash: 3 }, { name: 'Major', level: 17, damage: '4d8', splash: 4 }] },
  { name: 'Bottled Lightning', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d6', desc: 'Bottled lightning is packed with volatile reagents that create a blast of electricity when they’re exposed to air. Bottled lightning deals the listed electricity damage and electricity splash damage. On a hit, the target becomes off-guard until the start of your next turn. Many types grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d6 electricity damage and 1 electricity splash damage. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d6 electricity damage and 2 electricity splash damage. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d6 electricity damage and 3 electricity splash damage. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d6 electricity damage and 4 electricity splash damage.', tiers: [{ name: 'Lesser', level: 1, damage: '1d6', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d6', splash: 2 }, { name: 'Greater', level: 11, damage: '3d6', splash: 3 }, { name: 'Major', level: 17, damage: '4d6', splash: 4 }] },
  { name: 'Frost Vial', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d6', desc: 'The bright blue liquid reagents in this vial rapidly absorb heat when exposed to air. A frost vial deals the listed cold damage and cold splash damage. On a hit, the target takes a status penalty to its Speeds until the end of its next turn. Many types of frost vial also grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d6 cold damage and 1 cold splash damage, and the target takes a –5-foot penalty. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d6 cold damage and 2 cold splash damage, and the target takes a –10-foot penalty. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d6 cold damage and 3 cold splash damage, and the target takes a –10-foot penalty. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d6 cold damage and 4 cold splash damage, and the target takes a –15-foot penalty.', tiers: [{ name: 'Lesser', level: 1, damage: '1d6', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d6', splash: 2 }, { name: 'Greater', level: 11, damage: '3d6', splash: 3 }, { name: 'Major', level: 17, damage: '4d6', splash: 4 }] },
  { name: 'Blasting Stone', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d4', desc: 'When this pebble hits a creature or a hard surface, it explodes with a deafening bang. A blasting stone deals the listed sonic damage and sonic splash damage, and each creature within 10 feet of the space in which the stone exploded must succeed at a Fortitude saving throw with the listed DC or be deafened until the end of its next turn. Many types of blasting stones grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d4 sonic damage and 1 sonic splash damage, and the DC is 17. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d4 sonic damage and 2 sonic splash damage, and the DC is 20. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d4 sonic damage and 3 sonic splash damage, and the DC is 28. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d4 sonic damage and 4 sonic splash damage, and the DC is 36.', tiers: [{ name: 'Lesser', level: 1, damage: '1d4', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d4', splash: 2 }, { name: 'Greater', level: 11, damage: '3d4', splash: 3 }, { name: 'Major', level: 17, damage: '4d4', splash: 4 }] },
  { name: 'Blight Bomb', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d4+1d4', desc: 'Blight bombs contain volatile toxic chemicals that rot flesh. A blight bomb deals the listed poison damage, persistent poison damage, and splash damage. Many types grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d4 poison damage, 1d4 persistent poison damage, and 1 poison splash damage. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d4 poison damage, 2d4 persistent poison damage, and 2 poison splash damage. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d4 poison damage, 3d4 persistent poison damage, and 3 poison splash damage. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d4 poison damage, 4d4 persistent poison damage, and 4 poison splash damage.', tiers: [{ name: 'Lesser', level: 1, damage: '1d4+1d4', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d4+2d4', splash: 2 }, { name: 'Greater', level: 11, damage: '3d4+3d4', splash: 3 }, { name: 'Major', level: 17, damage: '4d4+4d4', splash: 4 }] },
  { name: 'Dread Ampoule', category: 'bomb', level: 1, book: 'player-core-2', damage: '1d6', desc: 'This flask is filled with a murky purple gas that briefly interferes with normal brain activity. A dread ampoule deals the listed mental damage and mental splash damage. On a hit, the target becomes frightened 1, or frightened 2 on a critical hit. Many types also grant an item bonus to attack rolls. Lesser (Item 1): The bomb deals 1d6 mental damage and 1 mental splash damage. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The bomb deals 2d6 mental damage and 2 mental splash damage. Greater (Item 11): You gain a +2 item bonus to attack rolls. The bomb deals 3d6 mental damage and 3 mental splash damage. Major (Item 17): You gain a +3 item bonus to attack rolls. The bomb deals 4d6 mental damage and 4 mental splash damage.', tiers: [{ name: 'Lesser', level: 1, damage: '1d6', splash: 1 }, { name: 'Moderate', level: 3, damage: '2d6', splash: 2 }, { name: 'Greater', level: 11, damage: '3d6', splash: 3 }, { name: 'Major', level: 17, damage: '4d6', splash: 4 }] },
  { name: 'Glue Bomb', category: 'bomb', level: 1, book: 'player-core-2', desc: 'A glue bomb is a harmless explosive mechanism bursting with sticky substances. When you hit a creature with a glue bomb, that creature takes a status penalty to its Speeds for 1 minute. Many types of glue bomb also grant an item bonus to attack rolls. On a critical hit, a creature in contact with a solid surface becomes stuck to the surface and immobilized for 1 round, and a creature flying via wings has its wings tangled, causing it to fall safely to the ground and become unable to Fly again for 1 round. Glue bombs aren’t effective when used on a creature that’s in water. The target can end any effects by Escaping or spending a total of 3 manipulate actions to carefully remove the sticky substances. These manipulate actions don’t have to be consecutive, and other creatures can provide the actions as well. Lesser (Item 1): The target takes a –10-foot penalty, and the Escape DC is 17. Moderate (Item 3): You gain a +1 item bonus to attack rolls. The target takes a –15-foot penalty, and the Escape DC is 19. Greater (Item 11): You gain a +2 item bonus to attack rolls. The target takes a –15-foot penalty, and the Escape DC is 28. Major (Item 17): You gain a +3 item bonus to attack rolls. The target takes a –20-foot penalty, and the Escape DC is 37.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Elixir of Life', category: 'elixir', level: 1, book: 'player-core-2', damage: '1d6', desc: 'Elixirs of life accelerate a living creature’s natural healing processes and immune system. Upon drinking this elixir, you regain the listed number of Hit Points and gain an item bonus to saving throws against diseases and poisons for 10 minutes. Minor (Item 1): The elixir restores 1d6 Hit Points, and the bonus is +1. Lesser (Item 5): The elixir restores 3d6+6 Hit Points, and the bonus is +1. Moderate (Item 9): The elixir restores 5d6+12 Hit Points, and the bonus is +2. Greater (Item 13): The elixir restores 7d6+18 Hit Points, and the bonus is +2. Major (Item 15): The elixir restores 8d6+21 Hit Points, and the bonus is +3. True (Item 19): The elixir restores 10d6+27 Hit Points, and the bonus is +4.', tiers: [{ name: 'Minor', level: 1, damage: '1d6' }, { name: 'Lesser', level: 5, damage: '3d6' }, { name: 'Moderate', level: 9, damage: '5d6' }, { name: 'Greater', level: 13, damage: '7d6' }, { name: 'Major', level: 15, damage: '8d6' }, { name: 'True', level: 19, damage: '10d6' }] },
  { name: 'Cheetah’s Elixir', category: 'elixir', level: 1, book: 'player-core-2', desc: 'Enzymatic compounds in this elixir strengthen and excite the muscles in your legs. You gain a status bonus to your Speed for the listed duration. Lesser (Item 1): The bonus is +5 feet, and the duration is 1 minute. Moderate (Item 5): The bonus is +10 feet, and the duration is 10 minutes. Greater (Item 9): The bonus is +10 feet, and the duration is 1 hour.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 5 }, { name: 'Greater', level: 9 }] },
  { name: 'Eagle-Eye Elixir', category: 'elixir', level: 1, book: 'player-core-2', desc: 'After you drink this elixir, you notice subtle visual details. For the next hour, you gain an item bonus to Perception checks that’s greater when attempting to find secret doors and traps. Lesser (Item 1): The bonus is +1, or +2 to find secret doors and traps. Moderate (Item 5): The bonus is +2, or +3 to find secret doors and traps. Greater (Item 10): The bonus is +3, or +4 to find secret doors and traps. Major (Item 16): The bonus is +3, or +4 to find secret doors and traps. Each time you pass within 10 feet of a secret door or trap, the GM automatically rolls a secret check for you to find it.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 5 }, { name: 'Greater', level: 10 }, { name: 'Major', level: 16 }] },
  { name: 'Darkvision Elixir', category: 'elixir', level: 2, book: 'player-core-2', desc: 'After you drink this elixir, your sight becomes sharper in darkness. You gain darkvision for the listed duration. Lesser (Item 2): The duration is 10 minutes. Moderate (Item 4): The duration is 1 hour. Greater (Item 8): The duration is 24 hours.', tiers: [{ name: 'Lesser', level: 2 }, { name: 'Moderate', level: 4 }, { name: 'Greater', level: 8 }] },
  { name: 'Antidote', category: 'elixir', level: 1, book: 'player-core-2', desc: 'An antidote protects you against toxins. Upon drinking an antidote, you gain an item bonus to Fortitude saving throws against poisons for 6 hours. Lesser (Item 1): You gain a +2 item bonus. Moderate (Item 6): You gain a +3 item bonus. Greater (Item 10): You gain a +4 item bonus. Major (Item 14): You gain a +4 item bonus, and when you drink the antidote, you can immediately attempt a save against one poison of 14th level or lower affecting you. If you succeed, the poison is neutralized.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 6 }, { name: 'Greater', level: 10 }, { name: 'Major', level: 14 }] },
  { name: 'Antiplague', category: 'elixir', level: 1, book: 'player-core-2', desc: 'Antiplague can fortify the body’s defenses against diseases. Upon drinking an antiplague, you gain an item bonus to Fortitude saving throws against diseases for 24 hours; this applies to your daily save against a disease’s progression. Lesser (Item 1): You gain a +2 item bonus. Moderate (Item 6): You gain a +3 item bonus. Greater (Item 10): You gain a +4 item bonus. Major (Item 14): You gain a +4 item bonus, and when you drink the antiplague, you can immediately attempt a saving throw against one disease of 14th level or lower affecting you. If you succeed, you’re cured of the disease.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 6 }, { name: 'Greater', level: 10 }, { name: 'Major', level: 14 }] },
  { name: 'Comprehension Elixir', category: 'elixir', level: 2, book: 'player-core-2', desc: 'This bitter draft opens your mind to the potential of the written word. For the listed duration after drinking this elixir, you can understand any words you read, as long as they’re written in a common language. This elixir doesn’t automatically allow you to understand codes or extremely esoteric passages—you still need to attempt a skill check to Decipher Writing. Lesser (Item 2): The duration is 1 minute. Greater (Item 7): The duration is 10 minutes.', tiers: [{ name: 'Lesser', level: 2 }, { name: 'Greater', level: 7 }] },
  { name: 'Cat’s Eye Elixir', category: 'elixir', level: 2, book: 'player-core-2', desc: 'After you consume this elixir, your vision sharpens, and you become sensitive to even the most minute movements. For the next minute, you reduce the flat check to target hidden creatures to 5, and you don’t need to attempt a flat check to target concealed creatures. These benefits apply only against creatures within 30 feet of you.' },
  { name: 'Bravo’s Brew', category: 'elixir', level: 2, book: 'player-core-2', desc: 'This flask of foaming beer grants courage. For the next hour after drinking this elixir, you gain an item bonus to Will saves, which is greater when attempting Will saves against fear. Lesser (Item 2): The bonus on Will saves is +1, or +2 against fear. Moderate (Item 10): The bonus on Will saves is +2, or +3 against fear. Greater (Item 15): The bonus on Will saves is +3, or +4 against fear. If you roll a success on a save against fear, you get a critical success instead.', tiers: [{ name: 'Lesser', level: 2 }, { name: 'Moderate', level: 10 }, { name: 'Greater', level: 15 }] },
  { name: 'Elixir of Rejuvenation', category: 'elixir', level: 20, book: 'player-core-2', desc: 'The elixir of rejuvenation restores a creature to full health and eradicates toxins affecting it. When you drink this elixir, you’re restored to your maximum Hit Points, and all afflictions of 20th level or lower affecting you are removed. You can instead administer this elixir to a creature that has been dead for a week or less. When you do, that creature is instantly brought back to life with 1 Hit Point and no spell slots, Focus Points, or other daily resources. Craft Requirements philosopher’s stone, true elixir of life' },
  { name: 'Bestial Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', damage: '1d4+1d6', desc: 'Your features transform into something bestial and lumbering. Benefit You gain an item bonus to Athletics checks and unarmed attack rolls. You gain a claw unarmed attack with the agile trait and a jaws unarmed attack. Striking runes don’t modify the damage caused by these attacks. Drawback You take a –2 penalty to Reflex saves, Acrobatics checks, and Stealth checks. Lesser (Item 1): You gain a +1 item bonus, your claw deals 1d4 slashing damage, your jaws deal 1d6 piercing damage, and the duration is 1 minute. Moderate (Item 3): You gain a +2 item bonus, your claw deals 2d6 slashing damage, your jaws deal 2d8 piercing damage, and the duration is 10 minutes. Greater (Item 11): You gain a +3 item bonus, your claw deals 3d8 slashing damage, your jaws deal 3d10 piercing damage, and the duration is 1 hour. Major (Item 17): You gain a +4 item bonus, your claw deals 4d8 slashing damage, your jaws deal 4d10 piercing damage, and the duration is 1 hour. You gain weapon specialization with the claw and jaws, or greater weapon specialization if you already have weapon specialization with these unarmed attacks.', tiers: [{ name: 'Lesser', level: 1, damage: '1d4+1d6' }, { name: 'Moderate', level: 3, damage: '2d6+2d8' }, { name: 'Greater', level: 11, damage: '3d8+3d10' }, { name: 'Major', level: 17, damage: '4d8+4d10' }] },
  { name: 'Cognitive Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'Your mind becomes clear, but physical matters seem ephemeral. Benefit You gain an item bonus to Arcana, Crafting, Lore, Occultism, and Society checks and all checks to Recall Knowledge. Your critical failures on Recall Knowledge checks become failures instead. Drawback You take a –2 penalty to weapon and unarmed attack rolls, Athletics checks, and Acrobatics checks. You can carry 2 less Bulk than normal before becoming encumbered, and the maximum Bulk you can carry is reduced by 4. Lesser (Item 1): The bonus is +1, and the duration is 1 minute. Moderate (Item 3): The bonus is +2, and the duration is 10 minutes. Greater (Item 11): The bonus is +3, and the duration is 1 hour. You become trained in one Intelligence-based skill, chosen at creation. Major (Item 17): The bonus is +4, and the duration is 1 hour. You become trained in one skill, chosen at creation.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Drakeheart Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'Your skin grows scales like a drake, and your eyesight become sharp and your pupils slitted, but your mind and reflexes slow. Benefit You gain the listed bonus to AC, a Dexterity cap of +2 (as usual, use your lowest Dexterity cap if you have more than one), and an item bonus to Perception checks. If you’re wearing armor, you still calculate your proficiency bonus to AC based on your proficiency in the armor you’re wearing, even if the drakeheart mutagen has a higher item bonus. You also gain the Final Surge action. Activate —Final Surge 1 Action Effect You Stride twice. The drakeheart mutagen’s duration ends. Drawback You take a –1 penalty to Will saves, Reflex saves, and all skill checks to Recall Knowledge. Lesser (Item 1): The item bonus to AC is +4, the item bonus to Perception is +1, and the duration is 1 minute or until you use Final Surge, whichever comes first. Moderate (Item 3): The item bonus to AC is +5, the item bonus to Perception is +2, and the duration is 10 minutes or until you use Final Surge, whichever comes first. Greater (Item 11): The item bonus to AC is +6, the item bonus to Perception is +3, and the duration is 1 hour or until you use Final Surge, whichever comes first. Major (Item 17): The item bonus to AC is +7, the item bonus to Perception is +4, and the duration is 1 hour or until you use Final Surge, whichever comes first.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Juggernaut Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'Your body becomes sturdy and ponderous. Benefit You gain an item bonus to Fortitude saves and the listed number of temporary Hit Points. Whenever you’re at maximum Hit Points for at least 1 minute, you regain the temporary Hit Points. Drawback You take a –2 penalty to Will saves, Perception checks, and initiative rolls. Lesser (Item 1): The bonus is +1, you gain 5 temporary Hit Points, and the duration is 1 minute. Moderate (Item 3): The bonus is +2, you gain 10 temporary Hit Points, and the duration is 10 minutes. Greater (Item 11): The bonus is +3, you gain 30 temporary Hit Points, and the duration is 1 hour. When you roll a success on a Fortitude save, you get a critical success instead. Major (Item 17): The bonus is +4, you gain 45 temporary Hit Points, and the duration is 1 hour. When you roll a success on a Fortitude save, you get a critical success instead, and your critical failures on Fortitude saves become failures instead.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Quicksilver Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'You become swifter and nimbler but also fragile. Benefit You gain an item bonus to Acrobatics checks, Stealth checks, Thievery checks, Reflex saves, and Dexterity-based attack rolls, and you gain the listed status bonus to your Speed. Drawback You take damage equal to twice your level; you can’t recover Hit Points lost in this way by any means while the mutagen lasts. You take a –2 penalty to Fortitude saves. Lesser (Item 1): The bonus to rolls is +1, the bonus to Speed is +5 feet, and the duration is 1 minute. Moderate (Item 3): The bonus to rolls is +2, the bonus to Speed is +10 feet, and the duration is 10 minutes. Greater (Item 11): The bonus to rolls is +3, the bonus to Speed is +15 feet, and the duration is 1 hour. Major (Item 17): The bonus to rolls is +4, the bonus to Speed is +20 feet, and the duration is 1 hour.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Serene Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'You gain inner serenity, but you find violence off-putting. Benefit You gain an item bonus to Will saves and Perception, Medicine, Nature, Religion, and Survival checks. This bonus improves when you attempt Will saves against mental effects. Drawback You take a –1 penalty to attack rolls and save DCs of offensive spells, and a –1 penalty per damage die to all weapon, unarmed attack, and spell damage. Lesser (Item 1): The bonus is +1, or +2 vs. mental, and the duration is 1 minute. Moderate (Item 3): The bonus is +2, or +3 vs. mental, and the duration is 10 minutes. Greater (Item 11): The bonus is +3, or +4 vs. mental, and the duration is 1 hour. When you roll a success on a Will save against a mental effect, you get a critical success instead. Major (Item 17): The bonus is +4, and the duration is 1 hour. When you roll a success on a Will save against a mental effect, you get a critical success instead, and your critical failures on Will saves against mental effects become failures instead.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Silvertongue Mutagen', category: 'mutagen', level: 1, book: 'player-core-2', desc: 'Your features become striking, and your voice becomes musical and commanding, though emotion clouds your reason. Benefit You gain an item bonus to Deception, Diplomacy, Intimidation, and Performance checks. Your critical failures with any of these skills become failures instead. Drawback You take a –2 penalty to Arcana, Crafting, Lore, Occultism, and Society checks. Choose one skill in which you’re trained; for the duration, you become untrained in that skill. Lesser (Item 1): The bonus is +1, and the duration is 1 minute. Moderate (Item 3): The bonus is +2, and the duration is 10 minutes. Greater (Item 11): The bonus is +3, and the duration is 1 hour. Major (Item 17): The bonus is +4, and the duration is 1 hour.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Moderate', level: 3 }, { name: 'Greater', level: 11 }, { name: 'Major', level: 17 }] },
  { name: 'Arsenic', category: 'poison', level: 1, book: 'player-core-2', damage: '1d4', desc: 'This toxin is a compound of arsenic and other substances. You can’t reduce your sickened condition while affected. Saving Throw DC 18 Fortitude; Onset 10 minutes; Maximum Duration 5 minutes; Stage 1 1d4 poison damage and sickened 1 (1 minute); Stage 2 1d6 poison damage and sickened 2 (1 minute); Stage 3 1d8 poison damage and sickened 3 (1 minute)' },
  { name: 'Giant Centipede Venom', category: 'poison', level: 1, book: 'player-core-2', damage: '1d4', desc: 'Giant centipede venom causes severe muscle stiffness and general fatigue. Saving Throw DC 17 Fortitude; Maximum Duration 6 rounds; Stage 1 1d4 poison damage (1 round); Stage 2 1d4 poison damage and fatigued (1 round); Stage 3 1d4 poison damage, clumsy 1, and fatigued (1 round)' },
  { name: 'Belladonna', category: 'poison', level: 2, book: 'player-core-2', damage: '1d6', desc: 'Sometimes called “deadly nightshade,” belladonna is a widely available toxin produced from a plant similar to a tomato. Saving Throw DC 19 Fortitude; Onset 10 minutes; Maximum Duration 30 minutes; Stage 1 dazzled (10 minutes); Stage 2 1d6 poison damage and sickened 1 (10 minutes); Stage 3 1d6 poison damage, confused, and sickened 1 (1 minute)' },
  { name: 'Black Adder Venom', category: 'poison', level: 2, book: 'player-core-2', damage: '1d4', desc: 'Adder venom is a simple but effective way to enhance a weapon. Saving Throw DC 18 Fortitude; Maximum Duration 3 rounds; Stage 1 1d4 poison damage (1 round); Stage 2 1d6 poison damage (1 round); Stage 3 1d8 poison damage (1 round)' },
  { name: 'Graveroot', category: 'poison', level: 3, book: 'player-core-2', damage: '1d8', desc: 'The opaque white sap from the graveroot shrub clouds the mind. Saving Throw DC 19 Fortitude; Maximum Duration 4 rounds; Stage 1 1d8 poison damage (1 round); Stage 2 1d10 poison damage and stupefied 1 (1 round); Stage 3 2d6 poison damage and stupefied 2 (1 round)' },
  { name: 'Fearflower Nectar', category: 'poison', level: 4, book: 'player-core-2', damage: '1d6', desc: 'The nectar of a night-blooming desert flower attacks a victim’s central nervous system and causes feelings of panic. Saving Throw DC 21 Fortitude; Maximum Duration 6 rounds; Stage 1 1d6 poison damage and frightened 1 (1 round); Stage 2 1d6 poison damage and frightened 2 (1 round); Stage 3 1d6 poison damage and frightened 3 (1 round)' },
  { name: 'Smoke Ball', category: 'tool', level: 1, book: 'player-core-2', desc: 'With a sharp twist of this item, you instantly create a screen of thick, opaque smoke in a burst centered on one corner of your space. All creatures within that area are concealed, and all other creatures are concealed to them. The smoke lasts for 1 minute or until dispersed by a strong wind. Lesser (Item 1): The radius of the burst is 5 feet. Greater (Item 7): The radius of the burst is 20 feet.', tiers: [{ name: 'Lesser', level: 1 }, { name: 'Greater', level: 7 }] },
  { name: 'Silver Salve', category: 'tool', level: 2, book: 'player-core-2', desc: 'You can slather this silvery paste onto one melee or ranged weapon, or 10 pieces of ammunition. Silver salve spoils quickly, so you must use a vial all at once. For the next hour, the weapon or ammunition counts as silver instead of its normal precious material (such as cold iron) for any physical damage it deals.' },
  { name: 'Snake Oil', category: 'tool', level: 1, book: 'player-core-2', desc: 'You can apply snake oil on a wound or other outward symptom of an affliction or condition (such as sores from a disease or discoloration from a poison). For the next hour, the symptom disappears, and the wounded or afflicted creature doesn’t feel as if it still has the wound or affliction, though all effects remain. A creature can uncover the ruse by succeeding at a DC 17 Perception check, but only if it uses a Seek action to specifically examine the snake oil’s effects.' },
  { name: 'Timeless Salts', category: 'tool', level: 4, book: 'player-core-2', desc: 'You sprinkle these salts onto a single object up to 10 cubic feet in volume and no more than 40 Bulk to preserve it for 1 week. The object doesn’t decay, and effects that require the object to be fresh don’t count the time passing during this duration as having elapsed. When sprinkled on a corpse, this extends the period in which a creature can be revived by magic as well as the wait time required before a corpse can be targeted again with talking corpse. The salts prevent ordinary pests from consuming the target (such as maggots for a corpse or moths for a piece of clothing). Any creature can use an Interact action to disperse the salts from an unattended object and end this effect.' },
  { name: 'Philosopher’s Stone', category: 'tool', level: 20, book: 'player-core-2', desc: 'An alchemist with the Craft Philosopher’s Stone feat adds the formula for this item to their formula book. This allows them to create a philosopher’s stone once per month during their daily preparations using advanced alchemy. Unlike other items created with advanced alchemy, the philosopher’s stone remains potent for 1 month or until the alchemist creates a new one. This is the only way to create a philosopher’s stone. At a glance, a philosopher’s stone appears to be an ordinary, sooty piece of natural rock. Breaking the rock open with a Force Open action (DC 35) reveals a cavity at the stone’s heart. The cavity is lined with a rare type of quicksilver that can transmute base metals into precious metals or create an elixir of rejuvenation. To use the quicksilver, you must be legendary in Crafting and have the Alchemical Crafting feat. You can then use the stone’s quicksilver for one of two effects. You can apply the stone’s quicksilver to an infused true elixir of life using an Interact action. This turns the elixir into an infused elixir of rejuvenation instantaneously. This doesn’t require any crafting time or additional materials. You can spend up to a month of downtime applying the quicksilver either to iron to create silver or to lead to create gold. Treat this as a 20th-level task to Earn Income using Crafting, except that you create 500 gp worth of your chosen metal per day on a success or 750 gp worth per day on a critical success.' },
];


